from pathlib import Path

def replace_once(path, old, new):
    p=Path(path)
    text=p.read_text()
    count=text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: expected 1 match, found {count}: {old[:100]!r}')
    p.write_text(text.replace(old,new,1))

